const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const binaryData = items[i].binary;
  const nombresArchivos = [];

  if (binaryData) {
    // Iteramos sobre cada propiedad dentro del objeto binario (attachment_0, attachment_1, etc.)
    for (const key in binaryData) {
      if (binaryData[key].fileName) {
        nombresArchivos.push(binaryData[key].fileName);
      }
    }
  }

  // Guardamos la lista de nombres en una nueva propiedad del JSON para usarla despu?s
  items[i].json.lista_adjuntos = nombresArchivos;
  // Tambi?n guardamos el conteo por si necesitas validar si enviaron 0 archivos
  items[i].json.total_adjuntos = nombresArchivos.length;
}

return items;

