const normalize = (s = '') =>
  String(s)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase()
    .trim();

const toLower = (s = '') => String(s).toLowerCase().trim();

const internalDomain = '@grupocinte.com';
const allowedExt = new Set(['pdf','doc','docx','jpg','jpeg','png','zip','rar','xls','xlsx','xlsm']);
const imageExt = new Set(['jpg','jpeg','png','gif','bmp','webp']);
const inlineNameRegex = /(LOGO|BANNER|SIGNATURE|FIRMA|INLINE|IMAGE\d*|IMG\d*|PIC\d*|SOY\d*)/i;

const corporateNoiseRegex = /(SGSST|POLITICA|POLITICAS|BIENESTAR|COMUNICADO|GESTION DOCUMENTAL|NOVEDADES MASIVAS|CURSO|CAPACITACION|SALUD OCUPACIONAL|INDUCCION CORPORATIVA|ISO\s*9001|ISO\s*14001|SEGURIDAD Y SALUD EN EL TRABAJO|SST)/i;
const selectionRegex = /(FELICIDADES|HAS SIDO SELECCIONAD|SELECCIONADO|SELECCIONADA)/i;
const formRegex = /(\bF[\s\-_]*0*03\b|\bF[\s\-_]*0*17\b|\bF[\s\-_]*0*18\b|\bSAGRILAFT\b|\bDIAN\b|\bDEPENDENCIA\b)/i;

function isInlineAttachment(att, name) {
  if (att?.isInline === true || att?.isInline === 'true' || att?.isInline === 1) return true;
  const cid = String(att?.contentId || att?.contentID || att?.['@odata.mediaContentId'] || '').trim();
  if (cid) return true;
  if (inlineNameRegex.test(name)) return true;
  const ext = (name.split('.').pop() || '').toLowerCase();
  const size = att?.size || att?.fileSize || 0;
  if (imageExt.has(ext) && size > 0 && size < 200000) return true;
  return false;
}

function classifyItem(original = {}, binaryData = {}) {
  const fromEmail = toLower(original.from?.emailAddress?.address || original.sender?.emailAddress?.address || '');
  const senderEmail = fromEmail;
  const senderName = original.from?.emailAddress?.name || original.sender?.emailAddress?.name || '';

  const toEmails = (original.toRecipients || [])
    .map(r => toLower(r.emailAddress?.address || ''))
    .filter(Boolean);
  const ccEmails = (original.ccRecipients || [])
    .map(r => toLower(r.emailAddress?.address || ''))
    .filter(Boolean);
  const bccEmails = (original.bccRecipients || [])
    .map(r => toLower(r.emailAddress?.address || ''))
    .filter(Boolean);

  const allRecipients = [...toEmails, ...ccEmails, ...bccEmails];
  const isInternalSender = fromEmail.endsWith(internalDomain);
  const hasExternalInTo = toEmails.some(e => !e.endsWith(internalDomain));
  const hasInternalInCc = ccEmails.some(e => e.endsWith(internalDomain));

  const subjectNorm = normalize(original.subject || '');
  const bodyPreviewNorm = normalize(original.bodyPreview || original.bodyText || '');
  const combinedText = `${subjectNorm} ${bodyPreviewNorm}`;

  const isReplyOrForward = /^(RE|RV|FW|FWD|ENC)\s*:/i.test(String(original.subject || '').trim());
  const hasCorporateNoise = corporateNoiseRegex.test(combinedText);
  const hasSelectionPattern = selectionRegex.test(combinedText);

  const attachmentBag = [];
  for (const att of (original.attachments || [])) {
    const name = String(att?.name || att?.fileName || '').trim();
    const mime = String(att?.contentType || att?.mimeType || '').toLowerCase();
    if (!name && !mime) continue;
    attachmentBag.push({ name, mime, inline: isInlineAttachment(att, name.toUpperCase()) });
  }

  for (const key of Object.keys(binaryData || {})) {
    if (!key.startsWith('attachment')) continue;
    const b = binaryData[key] || {};
    const name = String(b.fileName || b.name || key).trim();
    const mime = String(b.mimeType || b.contentType || '').toLowerCase();
    attachmentBag.push({ name, mime, inline: isInlineAttachment(b, name.toUpperCase()) });
  }

  const dedupMap = new Map();
  for (const a of attachmentBag) {
    const k = `${a.name}|${a.mime}`;
    if (!dedupMap.has(k)) dedupMap.set(k, a);
  }
  const realAttachments = Array.from(dedupMap.values()).filter(a => !a.inline);

  const fileNames = realAttachments.map(a => a.name);
  const exts = realAttachments.map(a => (a.name.split('.').pop() || '').toLowerCase()).filter(Boolean);

  const hasRealAttachments = realAttachments.length > 0;
  const hasAllowedAttachments = exts.some(e => allowedExt.has(e));
  const hasExcel = exts.some(e => ['xls','xlsx','xlsm'].includes(e));
  const hasPdf = exts.includes('pdf');
  const hasZipRar = exts.some(e => ['zip','rar'].includes(e));
  const hasDoc = exts.some(e => ['doc','docx'].includes(e));
  const hasImg = exts.some(e => ['jpg','jpeg','png'].includes(e));

  // No evaluar forms con HTML crudo
  const formSource = normalize(`${fileNames.join(' ')} ${subjectNorm} ${bodyPreviewNorm}`);
  const hasFormsPattern = formRegex.test(formSource);

  const isSystemMailbox = /microsoftexchange|postmaster|mailer-daemon|no-reply|noreply/i.test(fromEmail);

  const shouldDrop =
    isSystemMailbox ||
    hasCorporateNoise ||
    (!hasRealAttachments && !hasSelectionPattern);

  let tipoCorreo = 'no_relacionado';
  let debeProcesarInicial = false;
  let debeProcesarDocumentosExcel = false;
  let debeProcesarDocumentosContratacion = false;

  if (!shouldDrop) {
    const isCase1 = isInternalSender && hasSelectionPattern && !isReplyOrForward && hasExternalInTo && hasInternalInCc;
    const isCase3 = !isInternalSender && isReplyOrForward && hasRealAttachments && hasAllowedAttachments && hasFormsPattern;
    const isCase2 = !isInternalSender && isReplyOrForward && hasRealAttachments && hasAllowedAttachments && !hasFormsPattern;

    if (isCase1) {
      tipoCorreo = 'correo_inicial';
      debeProcesarInicial = true;
    } else if (isCase3) {
      tipoCorreo = 'documentos_excel_diligenciados';
      debeProcesarDocumentosExcel = true;
    } else if (isCase2) {
      tipoCorreo = 'documentos_contratacion';
      debeProcesarDocumentosContratacion = true;
    }
  }

  return {
    ...original,
    senderEmail,
    senderName,
    tipoCorreo,
    debeProcesarInicial,
    debeProcesarDocumentosExcel,
    debeProcesarDocumentosContratacion,
    isInternalSender,
    isReplyOrForward,
    hasCorporateNoise,
    hasSelectionPattern,
    hasFormsPattern,
    hasRealAttachments,
    hasAllowedAttachments,
    hasExcel,
    hasPdf,
    hasDoc,
    hasImg,
    hasZipRar,
    fileNames,
    exts,
    toEmails,
    ccEmails,
    fromEmail,
    debug: {
      shouldDrop,
      hasExternalInTo,
      hasInternalInCc,
      allRecipients,
      reason: shouldDrop ? 'pre_bloqueo' : tipoCorreo,
    },
  };
}

const inputItems = $input.all();
if (!inputItems || inputItems.length === 0) {
  return [];
}

return inputItems.map((it, idx) => ({
  json: classifyItem(it.json || {}, it.binary || {}),
  binary: it.binary || {},
  pairedItem: { item: idx },
}));

// 1. Extraemos la respuesta de la IA (output del Agente)
const respuestaIA = $('AI Agent2').first().json.output || "Lo siento, hubo un error al procesar la respuesta.";

// 2. Recuperamos el tel?fono del nodo de DynamoDB y lo LIMPIAMOS
let telRaw = $input.first().json.whatsapp_numerico.N;
let telLimpio = "+" + telRaw.replace(/\D/g, "");

// 3. Construimos el JSON de Meta EXACTO
const metaPayload = {
  messaging_product: "whatsapp",
  recipient_type: "individual",
  to: telLimpio,
  type: "text",
  text: {
    body: respuestaIA
  }
};

// 4. Empaquetamos para AWS Social Messaging
return [{
  json: {
    message: Buffer.from(JSON.stringify(metaPayload)).toString('base64'),
    metaApiVersion: "v20.0",
    originationPhoneNumberId: "phone-number-id-8bde6f623e9d4234bc4608ec33923ed7"
  },
  pairedItem: { item: 0 }
}];

const emailData = $input.first();
const senderEmail = emailData.json.sender?.emailAddress?.address || emailData.json.from?.emailAddress?.address || '';
const senderName = emailData.json.sender?.emailAddress?.name || emailData.json.from?.emailAddress?.name || '';

const binary = emailData.binary || {};
const archivosValidos = [];

const allowedExt = new Set(['xlsx', 'xls', 'xlsm', 'pdf', 'doc', 'docx', 'zip', 'rar']);
const allowedMimeHints = [
  'spreadsheetml',
  'ms-excel',
  'pdf',
  'wordprocessingml',
  'msword',
  'zip',
  'x-rar',
  'vnd.rar',
  'x-7z-compressed',
];

Object.keys(binary).forEach((key, index) => {
  if (!key.startsWith('attachment')) return;

  const archivo = binary[key];
  const fileName = archivo.fileName || archivo.name || `archivo_${index}`;
  const mimeType = String(archivo.mimeType || '').toLowerCase();
  const ext = (fileName.split('.').pop() || '').toLowerCase();

  const permitidoPorExtension = allowedExt.has(ext);
  const permitidoPorMime = allowedMimeHints.some(h => mimeType.includes(h));
  const esValido = permitidoPorExtension || permitidoPorMime;

  if (!esValido) return;

  archivosValidos.push({
    json: {
      nombreArchivo: fileName,
      senderEmail,
      senderName,
      binaryKey: key,
      extension: ext,
      mimeType,
    },
    binary: { file: archivo },
    pairedItem: { item: index }
  });
});

if (archivosValidos.length === 0) {
  return [{
    json: { senderEmail, senderName, sinArchivos: true },
    pairedItem: { item: 0 }
  }];
}

return archivosValidos;

// Obtener datos del candidato desde DynamoDB
