  throw new Error('No se encontro el numero de WhatsApp del candidato.');
}

const telLimpio = '+' + whatsappNumber.toString().replace(/\D/g, '');

// Mensaje con opciones claras
const mensaje = `Hola ${nombreCandidato}, tu contrato ha sido enviado al correo electronico por medio de la aplicacion AUCO.\n\nPor favor revisa tu bandeja de entrada y tambien la carpeta de SPAM.\n\nUna vez que lo recibas, revisa y firma digitalmente.\n\n?Ya recibiste el contrato en tu correo?\n\nResponde:\n- 1 o SI si ya lo recibiste\n- 2 o NO si NO lo recibiste`;

// Payload WhatsApp
const whatsappPayload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: telLimpio,
  type: 'text',
  text: {
    body: mensaje
  }
};

return [{
  json: {
    message: Buffer.from(JSON.stringify(whatsappPayload)).toString('base64'),
    metaApiVersion: 'v20.0',
    originationPhoneNumberId: 'phone-number-id-8bde6f623e9d4234bc4608ec33923ed7'
  },
  pairedItem: { item: 0 }
}];

const items = $input.all();

if (items.length === 0) {
  return [];
}

// Ordenar por fecha (m?s reciente primero)
items.sort((a, b) => {
  const dateA = new Date(a.json.receivedDateTime || a.json.sentDateTime);
  const dateB = new Date(b.json.receivedDateTime || b.json.sentDateTime);
  return dateB - dateA;
});

// Retornar solo el m?s reciente
return [items[0]];

const carpetaRaizId = $input.first().json.d.UniqueId;

