  const binKey = Object.keys(binary)[0];
  if (!binKey || !binary[binKey]) {
    throw new Error('No se encontro contenido binario en el item.');
  }

  const b = binary[binKey];
  const fileName = String(json.nombreArchivo || 'Documento.docx');

  const lower = fileName.toLowerCase();
  let ext = 'docx';
  if (lower.endsWith('.pdf')) ext = 'pdf';
  else if (lower.endsWith('.doc')) ext = 'doc';
  else if (lower.endsWith('.docx')) ext = 'docx';

  let mime = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  if (ext === 'pdf') mime = 'application/pdf';
  if (ext === 'doc') mime = 'application/msword';

  b.fileName = fileName;
  b.fileExtension = ext;
  b.mimeType = mime;

  return {
    json,
    binary: {
      [binKey]: b,
    },
  };
});

