const itemsOriginales = $('Split Out1').all();
const binaryDataMap = {};

itemsOriginales.forEach(item => {
  const binary = item.binary || {};
  Object.keys(binary).forEach(key => {
    if (key.startsWith('attachment')) {
      const fileName = binary[key].fileName || binary[key].name || key;
      binaryDataMap[fileName] = { key: key, data: binary[key] };
    }
  });
});

const archivosParaSubir = [];

// Funci?n para normalizar nombres y eliminar tildes (NFD) o espacios ocultos
const normalizeString = (str) => {
  if (!str) return '';
  return str.normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .replace(/[^a-z0-9]/g, '');
};

