  const numeroCarpeta = doc.numeroCarpeta;
  const categoria = doc.categoria;
  let binaryInfo = null;

  // 1. Intento exacto
  if (binaryDataMap[nombreArchivo]) {
    binaryInfo = binaryDataMap[nombreArchivo];
  } else {
    // 2. Intento normalizado robusto (ignora tildes, may?sculas y caracteres raros)
    const normAiName = normalizeString(nombreArchivo);

    // Buscamos cu?l archivo f?sico coincide mejor
    const bestMatchKey = Object.keys(binaryDataMap).find(fileName => {
      const normFileName = normalizeString(fileName);
      return normFileName.includes(normAiName) || normAiName.includes(normFileName);
    });

    if (bestMatchKey) {
      binaryInfo = binaryDataMap[bestMatchKey];
    }
  }

  if (binaryInfo) {
    archivosParaSubir.push({
      nombreArchivo, 
      numeroCarpeta, 
      categoria,
      binaryKey: binaryInfo.key,
      binaryData: binaryInfo.data,
      nombreCandidato,
      cedula
    });
  }
});

